package com.ironquestprep;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.List;

import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.ObjectID;

public final class GatheringRouteBuilder {

    private static volatile WorldPoint routeOrigin;

    private GatheringRouteBuilder() {}

    public static List<GatheringStep> build(
            List<RequiredItem> requirements, BankTracker bankTracker) {
        WorldPoint origin = routeOrigin;

        if (origin == null) {
            return buildBaseSteps(requirements, bankTracker);
        }

        return build(requirements, bankTracker, origin);
    }

    public static List<GatheringStep> build(
            List<RequiredItem> requirements, BankTracker bankTracker, WorldPoint playerLocation) {
        if (playerLocation != null) {
            routeOrigin = playerLocation;
        }

        List<GatheringStep> baseSteps = buildBaseSteps(requirements, bankTracker);

        if (playerLocation == null || baseSteps.isEmpty()) {
            return baseSteps;
        }

        List<GatheringStep> navigable = new ArrayList<>();

        List<GatheringStep> unresolved = new ArrayList<>();

        for (GatheringStep step : baseSteps) {
            if (step != null
                    && step.hasNavigationTarget()
                    && step.getTarget() != null
                    && step.getTarget().getWorldPoint() != null) {
                navigable.add(step);
            } else {
                unresolved.add(step);
            }
        }

        if (navigable.isEmpty()) {
            return baseSteps;
        }

        List<GatheringStep> ordered = buildNearestRoute(navigable, playerLocation);

        ordered.addAll(unresolved);

        return ordered;
    }

    private static List<GatheringStep> buildBaseSteps(
            List<RequiredItem> requirements, BankTracker bankTracker) {
        List<GatheringStep> steps = new ArrayList<>();

        if (requirements == null || bankTracker == null) {
            return steps;
        }

        for (RequiredItem item : requirements) {
            if (item == null) {
                continue;
            }

            int missing = item.getMissingQuantity(bankTracker);

            if (missing <= 0) {
                continue;
            }

            AcquisitionRegion region = item.getRegion();

            if (region == null) {
                region = AcquisitionRegion.UNKNOWN;
            }

            String location = normaliseLocation(item, region);

            String instruction = item.getBestMethod();

            if (instruction == null || instruction.trim().isEmpty()) {
                instruction = "Obtain " + missing + " x " + item.getName() + ".";
            }

            GatheringStep baseStep =
                    new GatheringStep(
                            region,
                            location,
                            item.getName(),
                            item.getItemIds(),
                            missing,
                            instruction,
                            item.getMethodType());

            GatheringTarget target = GatheringTargetResolver.resolve(baseStep);

            GatheringStep finalStep = baseStep.withTarget(target);

            finalStep = applyMultiStageRoute(finalStep, item.getRequiredQuantity(), bankTracker);

            steps.add(finalStep);
        }

        steps.sort(baseComparator());

        return steps;
    }

    private static GatheringStep applyMultiStageRoute(
            GatheringStep step, int totalRequired, BankTracker bankTracker) {
        if (step == null) {
            return null;
        }

        // A recipe must not replace an explicitly selected shop or spawn route.
        if (step.getMethodType() != AcquisitionInfo.MethodType.CRAFT
                && step.getMethodType() != AcquisitionInfo.MethodType.GATHER) {
            return step;
        }

        String itemName = safeText(step.getItemName());

        if (itemName.equalsIgnoreCase("Ball of wool")) {
            int quantityRequired = Math.max(1, totalRequired);

            int[] finalItemIds = step.getItemIds();

            int[] woolOrBalls = combineIds(new int[] {ItemID.WOOL}, finalItemIds);

            GatheringStage shearStage =
                    new GatheringStage(
                            "Shear sheep",
                            "Shear sheep in the field north of Lumbridge until you have enough wool.",
                            GatheringTarget.area(
                                    "Lumbridge sheep field", new WorldPoint(3201, 3268, 0)),
                            woolOrBalls,
                            quantityRequired);

            GatheringStage spinStage =
                    new GatheringStage(
                            "Spin wool",
                            "Use the spinning wheel upstairs in Lumbridge Castle to spin the wool into balls of wool.",
                            GatheringTarget.object(
                                    ObjectID.SPINNINGWHEEL,
                                    "Lumbridge Castle spinning wheel",
                                    new WorldPoint(3209, 3212, 1)),
                            finalItemIds,
                            quantityRequired);

            GatheringStep staged = step.withStages(Arrays.asList(shearStage, spinStage));

            return exposeCurrentStage(staged, bankTracker);
        }

        if (itemName.equalsIgnoreCase("Pot of flour")) {
            int finalQuantityRequired = Math.max(1, totalRequired);

            int productionQuantity = Math.max(1, step.getQuantityNeeded());

            int[] finalItemIds = step.getItemIds();

            GatheringStage potStage =
                    new GatheringStage(
                            "Get empty pots",
                            "Get enough empty pots to collect the flour. Buy any missing pots from the Lumbridge General Store.",
                            GatheringTarget.area(
                                    "Lumbridge General Store", new WorldPoint(3212, 3246, 0)),
                            new int[] {ItemID.POT_EMPTY},
                            productionQuantity);

            GatheringStage grainStage =
                    new GatheringStage(
                            "Pick grain",
                            "Pick enough wheat from the field beside Mill Lane Mill.",
                            GatheringTarget.area(
                                    "Lumbridge wheat field", new WorldPoint(3161, 3292, 0)),
                            new int[] {ItemID.GRAIN},
                            productionQuantity);

            GatheringPrerequisite emptyPotPrerequisite =
                    new GatheringPrerequisite(
                            "Empty pot",
                            ItemID.POT_EMPTY,
                            productionQuantity,
                            "You need one empty pot for each remaining pot of flour.",
                            true);

            GatheringPrerequisite grainPrerequisite =
                    new GatheringPrerequisite(
                            "Grain",
                            ItemID.GRAIN,
                            productionQuantity,
                            "You need one grain for each remaining pot of flour.",
                            true);

            GatheringStage millStage =
                    new GatheringStage(
                            "Make flour",
                            "Take the grain upstairs, fill the hopper, operate the controls, then return downstairs and collect the flour using the empty pots.",
                            GatheringTarget.area("Mill Lane Mill", new WorldPoint(3166, 3306, 0)),
                            finalItemIds,
                            finalQuantityRequired,
                            Arrays.asList(emptyPotPrerequisite, grainPrerequisite));

            GatheringStep staged = step.withStages(Arrays.asList(potStage, grainStage, millStage));

            return exposeCurrentStage(staged, bankTracker);
        }

        return step;
    }

    private static GatheringStep exposeCurrentStage(GatheringStep staged, BankTracker bankTracker) {
        if (staged == null) {
            return null;
        }

        GatheringStage currentStage = staged.getCurrentStage(bankTracker);

        if (currentStage == null) {
            return staged;
        }

        String stageInstruction = currentStage.getName() + ": " + currentStage.getInstruction();

        if (currentStage.hasCompletionRequirement()) {
            stageInstruction +=
                    " ["
                            + currentStage.getOwnedQuantity(bankTracker)
                            + "/"
                            + currentStage.getCompletionQuantity()
                            + "]";
        }

        if (currentStage.hasPrerequisites()) {
            String prerequisiteText = currentStage.getPrerequisiteStatusText(bankTracker);

            if (prerequisiteText != null && !prerequisiteText.isEmpty()) {
                stageInstruction += " Requires: " + prerequisiteText + ".";
            }
        }

        return new GatheringStep(
                staged.getRegion(),
                staged.getLocation(),
                staged.getItemName(),
                staged.getItemIds(),
                staged.getQuantityNeeded(),
                stageInstruction,
                staged.getMethodType(),
                currentStage.getTarget(),
                staged.getStages());
    }

    private static int[] combineIds(int[] first, int[] second) {
        int firstLength = first == null ? 0 : first.length;

        int secondLength = second == null ? 0 : second.length;

        int[] combined = new int[firstLength + secondLength];

        int index = 0;

        if (first != null) {
            for (int id : first) {
                combined[index++] = id;
            }
        }

        if (second != null) {
            for (int id : second) {
                boolean duplicate = false;

                for (int i = 0; i < index; i++) {
                    if (combined[i] == id) {
                        duplicate = true;

                        break;
                    }
                }

                if (!duplicate) {
                    combined[index++] = id;
                }
            }
        }

        if (index == combined.length) {
            return combined;
        }

        return Arrays.copyOf(combined, index);
    }

    private static List<GatheringStep> buildNearestRoute(
            List<GatheringStep> input, WorldPoint startPoint) {
        List<GatheringStep> remaining = new ArrayList<>(input);

        List<GatheringStep> ordered = new ArrayList<>();

        WorldPoint currentPoint = startPoint;

        while (!remaining.isEmpty()) {
            GatheringStep nearest = findNearestStep(remaining, currentPoint);

            if (nearest == null) {
                break;
            }

            ordered.add(nearest);

            remaining.remove(nearest);

            WorldPoint targetPoint = nearest.getTarget().getWorldPoint();

            if (targetPoint != null) {
                currentPoint = targetPoint;
            }
        }

        ordered.addAll(remaining);

        return ordered;
    }

    private static GatheringStep findNearestStep(List<GatheringStep> steps, WorldPoint from) {
        GatheringStep best = null;

        long bestDistance = Long.MAX_VALUE;

        for (GatheringStep step : steps) {
            if (step == null || step.getTarget() == null) {
                continue;
            }

            WorldPoint destination = step.getTarget().getWorldPoint();

            if (destination == null) {
                continue;
            }

            long distance = distanceScore(from, destination);

            if (distance < bestDistance) {
                best = step;

                bestDistance = distance;

                continue;
            }

            if (distance == bestDistance && best != null && compareSteps(step, best) < 0) {
                best = step;
            }
        }

        return best;
    }

    private static long distanceScore(WorldPoint first, WorldPoint second) {
        if (first == null || second == null) {
            return Long.MAX_VALUE;
        }

        long deltaX = Math.abs((long) first.getX() - second.getX());

        long deltaY = Math.abs((long) first.getY() - second.getY());

        long distance = Math.max(deltaX, deltaY);

        if (first.getPlane() != second.getPlane()) {
            distance += 10000L;
        }

        return distance;
    }

    private static Comparator<GatheringStep> baseComparator() {
        return new Comparator<GatheringStep>() {
            @Override
            public int compare(GatheringStep first, GatheringStep second) {
                return compareSteps(first, second);
            }
        };
    }

    private static int compareSteps(GatheringStep first, GatheringStep second) {
        int regionCompare =
                Integer.compare(
                        first.getRegion().getSortOrder(), second.getRegion().getSortOrder());

        if (regionCompare != 0) {
            return regionCompare;
        }

        int locationCompare =
                String.CASE_INSENSITIVE_ORDER.compare(
                        safeText(first.getLocation()), safeText(second.getLocation()));

        if (locationCompare != 0) {
            return locationCompare;
        }

        return String.CASE_INSENSITIVE_ORDER.compare(
                safeText(first.getItemName()), safeText(second.getItemName()));
    }

    private static String normaliseLocation(RequiredItem item, AcquisitionRegion region) {
        String location = item.getLocation();

        if (location != null && !location.trim().isEmpty()) {
            return location.trim();
        }

        if (region == AcquisitionRegion.UNKNOWN) {
            return "Unresearched items";
        }

        if (region == AcquisitionRegion.ANYWHERE) {
            return "Any suitable location";
        }

        return "General / multiple locations";
    }

    private static String safeText(String value) {
        return value == null ? "" : value.trim();
    }
}

package com.ironquestprep;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public final class GatheringStep
{
    private final AcquisitionRegion region;
    private final String location;
    private final String itemName;
    private final int[] itemIds;
    private final int quantityNeeded;
    private final String instruction;
    private final AcquisitionInfo.MethodType methodType;

    private final GatheringTarget target;

    private final List<GatheringStage> stages;

    public GatheringStep(
            AcquisitionRegion region,
            String location,
            String itemName,
            int[] itemIds,
            int quantityNeeded,
            String instruction,
            AcquisitionInfo.MethodType methodType)
    {
        this(
                region,
                location,
                itemName,
                itemIds,
                quantityNeeded,
                instruction,
                methodType,
                GatheringTarget.none(),
                Collections.emptyList()
        );
    }

    public GatheringStep(
            AcquisitionRegion region,
            String location,
            String itemName,
            int[] itemIds,
            int quantityNeeded,
            String instruction,
            AcquisitionInfo.MethodType methodType,
            GatheringTarget target)
    {
        this(
                region,
                location,
                itemName,
                itemIds,
                quantityNeeded,
                instruction,
                methodType,
                target,
                Collections.emptyList()
        );
    }

    public GatheringStep(
            AcquisitionRegion region,
            String location,
            String itemName,
            int[] itemIds,
            int quantityNeeded,
            String instruction,
            AcquisitionInfo.MethodType methodType,
            GatheringTarget target,
            List<GatheringStage> stages)
    {
        this.region =
                region == null
                        ? AcquisitionRegion.UNKNOWN
                        : region;

        this.location =
                location == null
                        ? ""
                        : location.trim();

        this.itemName =
                itemName == null
                        ? ""
                        : itemName.trim();

        this.itemIds =
                itemIds == null
                        ? new int[0]
                        : itemIds.clone();

        this.quantityNeeded =
                Math.max(
                        0,
                        quantityNeeded
                );

        this.instruction =
                instruction == null
                        ? ""
                        : instruction.trim();

        this.methodType =
                methodType == null
                        ? AcquisitionInfo.MethodType.UNKNOWN
                        : methodType;

        this.target =
                target == null
                        ? GatheringTarget.none()
                        : target;

        if (stages == null
                || stages.isEmpty())
        {
            this.stages =
                    Collections.emptyList();
        }
        else
        {
            List<GatheringStage> safeStages =
                    new ArrayList<>();

            for (GatheringStage stage : stages)
            {
                if (stage != null)
                {
                    safeStages.add(
                            stage
                    );
                }
            }

            this.stages =
                    Collections.unmodifiableList(
                            safeStages
                    );
        }
    }

    public AcquisitionRegion getRegion()
    {
        return region;
    }

    public String getLocation()
    {
        return location;
    }

    public String getItemName()
    {
        return itemName;
    }

    public int[] getItemIds()
    {
        return itemIds.clone();
    }

    public int getQuantityNeeded()
    {
        return quantityNeeded;
    }

    public String getInstruction()
    {
        return instruction;
    }

    public AcquisitionInfo.MethodType getMethodType()
    {
        return methodType;
    }

    public GatheringTarget getTarget()
    {
        return target;
    }

    public boolean hasNavigationTarget()
    {
        return target != null
                && target.isNavigable();
    }

    public List<GatheringStage> getStages()
    {
        return stages;
    }

    public boolean hasStages()
    {
        return !stages.isEmpty();
    }

    public GatheringStage getCurrentStage(
            BankTracker bankTracker)
    {
        if (stages.isEmpty())
        {
            return null;
        }

        for (GatheringStage stage : stages)
        {

            if (!stage.hasCompletionRequirement())
            {
                return stage;
            }

            if (!stage.isComplete(
                    bankTracker))
            {
                return stage;
            }
        }

        return null;
    }

    public boolean areAllStagesComplete(
            BankTracker bankTracker)
    {
        if (stages.isEmpty())
        {
            return false;
        }

        for (GatheringStage stage : stages)
        {
            if (!stage.hasCompletionRequirement())
            {
                return false;
            }

            if (!stage.isComplete(
                    bankTracker))
            {
                return false;
            }
        }

        return true;
    }

    public GatheringTarget getCurrentTarget(
            BankTracker bankTracker)
    {
        GatheringStage currentStage =
                getCurrentStage(
                        bankTracker
                );

        if (currentStage != null
                && currentStage.getTarget() != null)
        {
            return currentStage.getTarget();
        }

        return target;
    }

    public GatheringStep withTarget(
            GatheringTarget newTarget)
    {
        return new GatheringStep(
                region,
                location,
                itemName,
                itemIds,
                quantityNeeded,
                instruction,
                methodType,
                newTarget,
                stages
        );
    }

    public GatheringStep withStages(
            List<GatheringStage> newStages)
    {
        return new GatheringStep(
                region,
                location,
                itemName,
                itemIds,
                quantityNeeded,
                instruction,
                methodType,
                target,
                newStages
        );
    }

    public GatheringStep withTargetAndStages(
            GatheringTarget newTarget,
            List<GatheringStage> newStages)
    {
        return new GatheringStep(
                region,
                location,
                itemName,
                itemIds,
                quantityNeeded,
                instruction,
                methodType,
                newTarget,
                newStages
        );
    }
}

package com.ironquestprep;

import net.runelite.api.coords.WorldPoint;

public final class GatheringTarget
{
    public enum TargetType
    {
        NPC("NPC"),
        OBJECT("Object"),
        GROUND_ITEM("Ground item"),
        TILE("Tile"),
        AREA("Area"),
        NONE("None");

        private final String displayName;

        TargetType(
                String displayName)
        {
            this.displayName =
                    displayName;
        }

        public String getDisplayName()
        {
            return displayName;
        }
    }

    private final TargetType type;
    private final WorldPoint worldPoint;
    private final int targetId;
    private final String targetName;

    public GatheringTarget(
            TargetType type,
            WorldPoint worldPoint,
            int targetId,
            String targetName)
    {
        this.type =
                type == null
                        ? TargetType.NONE
                        : type;

        this.worldPoint =
                worldPoint;

        this.targetId =
                targetId;

        this.targetName =
                targetName == null
                        ? ""
                        : targetName.trim();
    }

    public static GatheringTarget npc(
            int npcId,
            String name,
            WorldPoint worldPoint)
    {
        return new GatheringTarget(
                TargetType.NPC,
                worldPoint,
                npcId,
                name
        );
    }

    public static GatheringTarget object(
            int objectId,
            String name,
            WorldPoint worldPoint)
    {
        return new GatheringTarget(
                TargetType.OBJECT,
                worldPoint,
                objectId,
                name
        );
    }

    public static GatheringTarget groundItem(
            int itemId,
            String name,
            WorldPoint worldPoint)
    {
        return new GatheringTarget(
                TargetType.GROUND_ITEM,
                worldPoint,
                itemId,
                name
        );
    }

    public static GatheringTarget tile(
            String name,
            WorldPoint worldPoint)
    {
        return new GatheringTarget(
                TargetType.TILE,
                worldPoint,
                -1,
                name
        );
    }

    public static GatheringTarget area(
            String name,
            WorldPoint worldPoint)
    {
        return new GatheringTarget(
                TargetType.AREA,
                worldPoint,
                -1,
                name
        );
    }

    public static GatheringTarget none()
    {
        return new GatheringTarget(
                TargetType.NONE,
                null,
                -1,
                ""
        );
    }

    public TargetType getType()
    {
        return type;
    }

    public WorldPoint getWorldPoint()
    {
        return worldPoint;
    }

    public int getTargetId()
    {
        return targetId;
    }

    public String getTargetName()
    {
        return targetName;
    }

    public boolean hasWorldPoint()
    {
        return worldPoint != null;
    }

    public boolean hasTargetId()
    {
        return targetId >= 0;
    }

    public boolean hasTargetName()
    {
        return !targetName.isEmpty();
    }

    public boolean isNavigable()
    {
        return type != TargetType.NONE
                && worldPoint != null;
    }

    /*
     * Example:
     *
     * 3097, 3257, 0
     */
    public String getCoordinateText()
    {
        if (worldPoint == null)
        {
            return "";
        }

        return worldPoint.getX()
                + ", "
                + worldPoint.getY()
                + ", "
                + worldPoint.getPlane();
    }

    /*
     * Human-readable target description for the
     * Gathering Route sidebar.
     *
     * Examples:
     *
     * NPC: Ned
     * Area: Mill Lane Mill
     * Ground item: Knife
     */
    public String getDisplayText()
    {
        if (type == TargetType.NONE)
        {
            return "No target";
        }

        if (hasTargetName())
        {
            return type.getDisplayName()
                    + ": "
                    + targetName;
        }

        return type.getDisplayName();
    }

    /*
     * Used by the panel so we can immediately see which
     * acquisition entries have usable navigation data.
     */
    public String getNavigationStatus()
    {
        if (type == TargetType.NONE)
        {
            return "No navigation target";
        }

        if (worldPoint != null)
        {
            return "Navigation ready";
        }

        if (hasTargetName())
        {
            return "Target recognised - coordinates needed";
        }

        return "Location data needed";
    }
}

package com.ironquestprep;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.util.HashSet;
import java.util.Set;
import javax.inject.Inject;

import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.Tile;
import net.runelite.api.TileItem;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

public class QuestGroundItemOverlay extends Overlay
{
    private static final Color PINK =
            new Color(
                    255,
                    20,
                    147
            );

    private static final Color PINK_FILL =
            new Color(
                    255,
                    20,
                    147,
                    35
            );

    private final Client client;
    private final QuestPrepPlugin plugin;
    private final QuestPrepConfig config;

    @Inject
    QuestGroundItemOverlay(
            Client client,
            QuestPrepPlugin plugin,
            QuestPrepConfig config)
    {
        this.client = client;
        this.plugin = plugin;
        this.config = config;

        setPosition(
                OverlayPosition.DYNAMIC
        );

        setLayer(
                OverlayLayer.ABOVE_SCENE
        );

        setPriority(
                PRIORITY_HIGH
        );
    }

    @Override
    public Dimension render(
            Graphics2D graphics)
    {
        /*
         * Ground-item highlighting is completely
         * independent from route guidance.
         */
        if (!config.showGroundMarkers() || !plugin.hasGroundItemLabels())
        {
            return null;
        }

        Set<Integer> renderedIds = new HashSet<>();
        for (Tile tile
                : plugin.getGroundItemTiles())
        {
            if (tile == null || tile.getPlane() != client.getPlane() || tile.getGroundItems() == null)
            {
                continue;
            }

            renderedIds.clear();

            int textOffset = 0;
            boolean tileHighlighted = false;

            for (TileItem tileItem
                    : tile.getGroundItems())
            {
                if (tileItem == null)
                {
                    continue;
                }

                int itemId =
                        tileItem.getId();

                if (!renderedIds.add(
                        itemId))
                {
                    continue;
                }

                String label =
                        plugin.getGroundItemLabel(
                                itemId
                        );

                if (label == null)
                {
                    continue;
                }

                if (!tileHighlighted)
                {
                    drawTileHighlight(
                            graphics,
                            tile
                    );

                    tileHighlighted = true;
                }

                String displayText =
                        label;

                if (tileItem.getQuantity() > 1)
                {
                    displayText +=
                            " | Ground x"
                                    + tileItem.getQuantity();
                }

                Point textLocation =
                        Perspective.getCanvasTextLocation(
                                client,
                                graphics,
                                tile.getLocalLocation(),
                                displayText,
                                0
                        );

                if (textLocation == null)
                {
                    continue;
                }

                Point adjusted =
                        new Point(
                                textLocation.getX(),
                                textLocation.getY()
                                        - textOffset
                        );

                OverlayUtil.renderTextLocation(
                        graphics,
                        adjusted,
                        displayText,
                        PINK
                );

                textOffset += 14;
            }
        }

        return null;
    }

    private void drawTileHighlight(
            Graphics2D graphics,
            Tile tile)
    {
        Polygon polygon =
                Perspective.getCanvasTilePoly(
                        client,
                        tile.getLocalLocation()
                );

        if (polygon == null)
        {
            return;
        }

        Color previous =
                graphics.getColor();

        graphics.setColor(
                PINK_FILL
        );

        graphics.fill(
                polygon
        );

        graphics.setColor(
                previous
        );

        OverlayUtil.renderPolygon(
                graphics,
                polygon,
                PINK
        );
    }
}

package com.ironquestprep;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

public final class RequirementGroup
{
    public enum Logic
    {
        AND,
        OR,
        CONDITIONAL
    }

    private final String key;
    private final Logic logic;
    private final String description;
    private final List<String> children;
    private final List<ConditionalBranch> branches;

    public RequirementGroup(
            String key,
            Logic logic,
            String description,
            String... children)
    {
        this(
                key,
                logic,
                description,
                Arrays.asList(children),
                Collections.emptyList()
        );
    }

    public RequirementGroup(
            String key,
            Logic logic,
            String description,
            List<String> children,
            List<ConditionalBranch> branches)
    {
        this.key =
                key == null
                        ? ""
                        : key;

        this.logic =
                logic == null
                        ? Logic.AND
                        : logic;

        this.description =
                description == null
                        ? ""
                        : description;

        this.children = Collections.unmodifiableList(
                new ArrayList<>(children)
        );

        this.branches = Collections.unmodifiableList(
                new ArrayList<>(branches)
        );
    }

    public String getKey()
    {
        return key;
    }

    public Logic getLogic()
    {
        return logic;
    }

    public String getDescription()
    {
        return description;
    }

    public List<String> getChildren()
    {
        return children;
    }

    public List<ConditionalBranch> getBranches()
    {
        return branches;
    }

    public boolean isConditional()
    {
        return logic == Logic.CONDITIONAL;
    }

    public static final class ConditionalBranch
    {
        public enum PredicateKind
        {
            ALWAYS,
            SKILL_RANGE,
            QUEST_FINISHED,
            LOGGED_IN_AND_QUEST_FINISHED
        }

        private final String child;
        private final PredicateKind predicateKind;
        private final String skill;
        private final int minimumLevel;
        private final int maximumLevel;
        private final String quest;
        private final boolean negate;

        private ConditionalBranch(
                String child,
                PredicateKind predicateKind,
                String skill,
                int minimumLevel,
                int maximumLevel,
                String quest,
                boolean negate)
        {
            this.child = child;
            this.predicateKind = predicateKind;
            this.skill = skill == null ? "" : skill;
            this.minimumLevel = minimumLevel;
            this.maximumLevel = maximumLevel;
            this.quest = quest == null ? "" : quest;
            this.negate = negate;
        }

        public static ConditionalBranch always(
                String child)
        {
            return new ConditionalBranch(
                    child,
                    PredicateKind.ALWAYS,
                    "",
                    0,
                    Integer.MAX_VALUE,
                    "",
                    false
            );
        }

        public static ConditionalBranch skillRange(
                String child,
                String skill,
                int minimumLevel,
                int maximumLevel)
        {
            return new ConditionalBranch(
                    child,
                    PredicateKind.SKILL_RANGE,
                    skill,
                    minimumLevel,
                    maximumLevel,
                    "",
                    false
            );
        }

        public static ConditionalBranch questFinished(
                String child,
                String quest)
        {
            return new ConditionalBranch(
                    child,
                    PredicateKind.QUEST_FINISHED,
                    "",
                    0,
                    Integer.MAX_VALUE,
                    quest,
                    false
            );
        }

        public static ConditionalBranch loggedInAndQuestFinished(
                String child,
                String quest,
                boolean negate)
        {
            return new ConditionalBranch(
                    child,
                    PredicateKind.LOGGED_IN_AND_QUEST_FINISHED,
                    "",
                    0,
                    Integer.MAX_VALUE,
                    quest,
                    negate
            );
        }

        public String getChild()
        {
            return child;
        }

        public PredicateKind getPredicateKind()
        {
            return predicateKind;
        }

        public String getSkill()
        {
            return skill;
        }

        public int getMinimumLevel()
        {
            return minimumLevel;
        }

        public int getMaximumLevel()
        {
            return maximumLevel;
        }

        public String getQuest()
        {
            return quest;
        }

        public boolean isNegate()
        {
            return negate;
        }
    }
}

package com.ironquestprep;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.HintArrowType;
import net.runelite.api.Point;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.worldmap.WorldMapPoint;
import net.runelite.client.ui.overlay.worldmap.WorldMapPointManager;

/** Destination changes use the client's hint arrow; there is no per-frame route overlay. */
public class RouteGuidanceOverlay {
    private static final Color PINK = new Color(255, 20, 147);
    private static final Color WHITE = Color.WHITE;
    private static final int WORLD_MAP_MARKER_WIDTH = 24;
    private static final int WORLD_MAP_MARKER_HEIGHT = 30;
    private static final BufferedImage WORLD_MAP_MARKER_IMAGE = createWorldMapMarkerImage();
    private final Client client;
    private final QuestPrepConfig config;
    private final WorldMapPointManager worldMapPointManager;
    private GatheringStep activeStep;
    private WorldMapPoint mapPoint;
    private WorldPoint ownedArrow;

    @Inject
    RouteGuidanceOverlay(Client client, QuestPrepConfig config, WorldMapPointManager manager) {
        this.client = client;
        this.config = config;
        this.worldMapPointManager = manager;
    }

    public GatheringStep getActiveStep() { return activeStep; }

    public void setActiveStep(GatheringStep step) {
        activeStep = step;
        if (step == null || !config.routeGuidance() || !step.hasNavigationTarget()) {
            clearMarkers();
            return;
        }
        WorldPoint point = step.getTarget().getWorldPoint();
        // Ownership refreshes must not repeatedly replace an arrow set by another plugin.
        if (mapPoint != null && point.equals(mapPoint.getWorldPoint())) return;
        clearMarkers();
        client.setHintArrow(point);
        ownedArrow = point;
        mapPoint = new WorldMapPoint(point, WORLD_MAP_MARKER_IMAGE);
        mapPoint.setImagePoint(new Point(WORLD_MAP_MARKER_WIDTH / 2, WORLD_MAP_MARKER_HEIGHT - 2));
        mapPoint.setName("Ironman Quest Prep - " + step.getItemName());
        mapPoint.setTooltip(step.getItemName() + "<br>" + step.getTarget().getDisplayText());
        mapPoint.setTarget(point);
        mapPoint.setJumpOnClick(true);
        mapPoint.setSnapToEdge(true);
        worldMapPointManager.add(mapPoint);
    }

    public void clearActiveStep() {
        activeStep = null;
        clearMarkers();
    }

    private void clearMarkers() {
        if (ownedArrow != null && ownsHintArrow(ownedArrow, client.getHintArrowType(), client.getHintArrowPoint())) client.clearHintArrow();
        ownedArrow = null;
        if (mapPoint != null) worldMapPointManager.remove(mapPoint);
        mapPoint = null;
    }

    static boolean ownsHintArrow(WorldPoint owned, int type, WorldPoint current) {
        return owned != null && type == HintArrowType.COORDINATE && owned.equals(current);
    }

    private static BufferedImage createWorldMapMarkerImage() {
        BufferedImage image =
                new BufferedImage(
                        WORLD_MAP_MARKER_WIDTH,
                        WORLD_MAP_MARKER_HEIGHT,
                        BufferedImage.TYPE_INT_ARGB);

        Graphics2D graphics = image.createGraphics();

        graphics.setRenderingHint(
                RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

        /*
         * Marker tail.
         */
        Polygon tail =
                new Polygon(
                        new int[] {7, WORLD_MAP_MARKER_WIDTH / 2, 17},
                        new int[] {17, WORLD_MAP_MARKER_HEIGHT - 2, 17},
                        3);

        graphics.setColor(PINK);

        graphics.fill(tail);

        /*
         * Main marker circle.
         */
        graphics.fillOval(2, 2, 20, 20);

        graphics.setColor(Color.BLACK);

        graphics.setStroke(new BasicStroke(2.0f));

        graphics.drawOval(2, 2, 20, 20);

        graphics.setColor(WHITE);

        graphics.fillOval(8, 8, 8, 8);

        graphics.dispose();

        return image;
    }

}

package com.ironquestprep;

public final class AcquisitionInfo
{
    public enum MethodType
    {
        SHOP("Shop"),
        SPAWN("Ground spawn"),
        GATHER("Gather"),
        CRAFT("Craft"),
        DROP("Monster drop"),
        NPC("NPC"),
        QUEST("Quest progression"),
        SKILLING("Skilling"),
        MULTIPLE("Multiple methods"),
        UNKNOWN("Needs review");

        private final String displayName;

        MethodType(String displayName)
        {
            this.displayName = displayName;
        }

        public String getDisplayName()
        {
            return displayName;
        }
    }

    private final String method;
    private final AcquisitionRegion region;
    private final String location;
    private final MethodType methodType;
    private final AcquisitionPlace place;

    public AcquisitionInfo(
            String method,
            AcquisitionRegion region,
            String location,
            MethodType methodType)
    {
        this(
                method,
                region,
                location,
                methodType,
                null
        );
    }

    public AcquisitionInfo(
            String method,
            AcquisitionRegion region,
            String location,
            MethodType methodType,
            AcquisitionPlace suppliedPlace)
    {
        this.method = safe(method);

        AcquisitionRegion cleanRegion = region == null
                ? AcquisitionRegion.UNKNOWN
                : region;

        String cleanLocation = safe(location);

        AcquisitionPlace resolvedPlace = suppliedPlace;

        if (resolvedPlace == null)
        {
            resolvedPlace = AcquisitionPlaceDatabase.infer(
                    cleanRegion,
                    cleanLocation,
                    this.method
            );
        }

        if (resolvedPlace != null)
        {
            if (cleanRegion == AcquisitionRegion.UNKNOWN)
            {
                cleanRegion = resolvedPlace.getRegion();
            }

            if (cleanLocation.isEmpty())
            {
                cleanLocation = resolvedPlace.getDisplayName();
            }
        }

        if (cleanRegion == AcquisitionRegion.UNKNOWN)
        {
            cleanRegion = AcquisitionRegion.ANYWHERE;
        }

        if (cleanLocation.isEmpty())
        {
            cleanLocation = "Multiple possible sources";
        }

        this.region = cleanRegion;
        this.location = cleanLocation;
        this.methodType = methodType == null
                ? MethodType.UNKNOWN
                : methodType;
        this.place = resolvedPlace == null
                ? AcquisitionPlaceDatabase.get(
                        AcquisitionPlaceDatabase.MULTIPLE_SOURCES
                )
                : resolvedPlace;
    }

    /**
     * Compatibility helper for generated notes that have not yet been given a
     * hand-authored route.  Unlike the old implementation this still produces
     * a complete, non-blank acquisition record.
     */
    public static AcquisitionInfo unknown(String method)
    {
        AcquisitionPlace place = AcquisitionPlaceDatabase.inferFromText(method);
        MethodType inferredType = inferMethodType(method);

        if (place != null)
        {
            return new AcquisitionInfo(
                    method,
                    place.getRegion(),
                    place.getDisplayName(),
                    inferredType,
                    place
            );
        }

        return new AcquisitionInfo(
                method,
                AcquisitionRegion.ANYWHERE,
                "Multiple possible sources",
                inferredType == MethodType.UNKNOWN
                        ? MethodType.MULTIPLE
                        : inferredType,
                AcquisitionPlaceDatabase.get(
                        AcquisitionPlaceDatabase.MULTIPLE_SOURCES
                )
        );
    }

    public static AcquisitionInfo anywhere(
            String method,
            MethodType methodType)
    {
        return new AcquisitionInfo(
                method,
                AcquisitionRegion.ANYWHERE,
                "Any suitable location",
                methodType,
                AcquisitionPlaceDatabase.get(
                        AcquisitionPlaceDatabase.ANY_SUITABLE_LOCATION
                )
        );
    }

    public AcquisitionInfo withAdditionalNote(String note)
    {
        String cleanNote = safe(note);

        if (cleanNote.isEmpty()
                || method.contains(cleanNote))
        {
            return this;
        }

        String combinedMethod;

        if (method.isEmpty())
        {
            combinedMethod = cleanNote;
        }
        else
        {
            combinedMethod = method + " Note: " + cleanNote;
        }

        return new AcquisitionInfo(
                combinedMethod,
                region,
                location,
                methodType,
                place
        );
    }

    public String getMethod()
    {
        return method;
    }

    public AcquisitionRegion getRegion()
    {
        return region;
    }

    public String getLocation()
    {
        return location;
    }

    public MethodType getMethodType()
    {
        return methodType;
    }

    public AcquisitionPlace getPlace()
    {
        return place;
    }

    public boolean hasMethod()
    {
        return !method.isEmpty();
    }

    public boolean hasLocation()
    {
        return !location.isEmpty();
    }

    public boolean hasSpecificPlace()
    {
        return place != null
                && place.isSpecific();
    }

    public static MethodType inferMethodType(String text)
    {
        String lower = safe(text).toLowerCase();

        if (lower.isEmpty())
        {
            return MethodType.UNKNOWN;
        }

        if (containsAny(
                lower,
                "buy ",
                "buy one",
                "buy some",
                "purchasable",
                "purchased",
                "shop",
                "for 1gp",
                "for 2 coins",
                "for 3 coins",
                "for 5 coins",
                "for 20k",
                "for 80k",
                "for 150k"))
        {
            return MethodType.SHOP;
        }

        if (containsAny(
                lower,
                "kill ",
                "killing ",
                "drops ",
                "drop from"))
        {
            return MethodType.DROP;
        }

        if (containsAny(
                lower,
                "mine ",
                "mined ",
                "chop ",
                "pick ",
                "picking ",
                "fish ",
                "shear ",
                "panning"))
        {
            return MethodType.GATHER;
        }

        if (containsAny(
                lower,
                "make ",
                "made ",
                "cook ",
                "grind ",
                "mix ",
                "smelt ",
                "smith ",
                "spin ",
                "use a knife",
                "using a knife",
                "use cooked",
                "convert "))
        {
            return MethodType.CRAFT;
        }

        if (containsAny(
                lower,
                "spawn",
                "pick up",
                "pick this up",
                "find one",
                "find a ",
                "search ",
                "searching ",
                "cabinet",
                "cupboard",
                "crate"))
        {
            return MethodType.SPAWN;
        }

        if (containsAny(
                lower,
                "during the quest",
                "during quest",
                "quest route",
                "quest step",
                "quest line",
                "obtainable in quest",
                "obtained in quest"))
        {
            return MethodType.QUEST;
        }

        if (containsAny(
                lower,
                "get another from",
                "get one from",
                "obtain from",
                "talk to",
                "give ",
                "from father ",
                "from rasolo",
                "from askeladden"))
        {
            return MethodType.NPC;
        }

        return MethodType.MULTIPLE;
    }

    private static boolean containsAny(
            String text,
            String... needles)
    {
        for (String needle : needles)
        {
            if (text.contains(needle))
            {
                return true;
            }
        }

        return false;
    }

    private static String safe(String value)
    {
        return value == null
                ? ""
                : value.trim();
    }
}

