            List<TargetRule> rules, String label, String placeKey, String required, String... any) {
        rules.add(new TargetRule(TargetKind.AREA, -1, label, placeKey, null, required, any));
    }

    private static void spawnPlace(
            List<TargetRule> rules, String label, String placeKey, String required, String... any) {
        rules.add(new TargetRule(TargetKind.SPAWN, -1, label, placeKey, null, required, any));
    }

    private static String safe(String value) {
        return value == null ? "" : value.trim();
    }

    private static String normalise(String value) {
        return safe(value).toLowerCase(Locale.ROOT);
    }

    /**
     * Phrase match with alphanumeric boundaries.
     *
     * This deliberately avoids raw String.contains() false positives such as
     * the NPC hint "ned" matching the word "needed".
     */
    static boolean containsHint(String text, String hint) {
        String cleanText = normalise(text);
        String cleanHint = normalise(hint);

        if (cleanText.isEmpty() || cleanHint.isEmpty()) {
            return false;
        }

        int fromIndex = 0;

        while (fromIndex < cleanText.length()) {
            int index = cleanText.indexOf(cleanHint, fromIndex);

            if (index < 0) {
                return false;
            }

            int end = index + cleanHint.length();

            boolean startBoundary =
                    index == 0 || !Character.isLetterOrDigit(cleanText.charAt(index - 1));

            boolean endBoundary =
                    end == cleanText.length() || !Character.isLetterOrDigit(cleanText.charAt(end));

            if (startBoundary && endBoundary) {
                return true;
            }

            fromIndex = index + 1;
        }

        return false;
    }

    private enum TargetKind {
        NPC,
        AREA,
        SPAWN
    }

    private static final class TargetRule {
        private final TargetKind kind;
        private final int npcId;
        private final String label;
        private final String placeKey;
        private final WorldPoint fixedPoint;
        private final String requiredHint;
        private final String[] anyHints;

        private TargetRule(
                TargetKind kind,
                int npcId,
                String label,
                String placeKey,
                WorldPoint fixedPoint,
                String requiredHint,
                String[] anyHints) {
            this.kind = kind;

            this.npcId = npcId;

            this.label = safe(label);

            this.placeKey = safe(placeKey);

            this.fixedPoint = fixedPoint;

            this.requiredHint = normalise(requiredHint);

            this.anyHints = anyHints == null ? new String[0] : anyHints.clone();
        }

        private boolean matchesRegion(GatheringStep step) {
            AcquisitionPlace source =
                    placeKey.isEmpty()
                            ? AcquisitionPlaceDatabase.inferFromText(label)
                            : AcquisitionPlaceDatabase.get(placeKey);
            AcquisitionPlace selected = AcquisitionPlaceDatabase.inferFromText(step.getLocation());
            AcquisitionRegion region = selected == null ? step.getRegion() : selected.getRegion();
            return source == null
                    || region == AcquisitionRegion.ANYWHERE
                    || region == AcquisitionRegion.UNKNOWN
                    || source.getRegion() == region;
        }

        private boolean matches(String text) {
            if (text == null || text.isEmpty()) {
                return false;
            }

            if (!requiredHint.isEmpty() && !containsHint(text, requiredHint)) {
                return false;
            }

            if (anyHints.length == 0) {
                return true;
            }

            for (String hint : anyHints) {
                if (containsHint(text, hint)) {
                    return true;
                }
            }

            return false;
        }

        private GatheringTarget create(GatheringStep step) {
            WorldPoint point = fixedPoint;

            if (point == null && !placeKey.isEmpty()) {
                point = AcquisitionNavigationDatabase.getWorldPoint(placeKey);
            }

            if (point == null) {
                return null;
            }

            if (kind == TargetKind.NPC) {
                return GatheringTarget.npc(npcId, label, point);
            }

            if (kind == TargetKind.SPAWN) {
                int[] ids = step.getItemIds();

                if (ids.length > 0 && step.getMethodType() == AcquisitionInfo.MethodType.SPAWN) {
                    return GatheringTarget.groundItem(ids[0], step.getItemName(), point);
                }
            }

            return GatheringTarget.area(label, point);
        }
    }
}

package com.ironquestprep;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

import net.runelite.api.Item;
import net.runelite.api.ItemContainer;

/** Tracks bank, shared storage and inventory quantities; snapshots isolate the sidebar. */
public class BankTracker
{
    private final Map<Integer, Integer> bankItems =
            new HashMap<>();

    private final Map<Integer, Integer> groupStorageItems =
            new HashMap<>();

    private final Map<Integer, Integer> inventoryItems =
            new HashMap<>();

    private boolean bankScanned = false;
    private boolean groupStorageScanned = false;
    private boolean inventoryScanned = false;

    public void scanBank(
            ItemContainer bank)
    {
        if (bank == null)
        {
            bankItems.clear();
            bankScanned = false;
            return;
        }

        scanContainer(
                bank,
                bankItems
        );

        bankScanned = true;
    }

    public void scanGroupStorage(
            ItemContainer groupStorage)
    {
        if (groupStorage == null)
        {
            groupStorageItems.clear();
            groupStorageScanned = false;
            return;
        }

        scanContainer(
                groupStorage,
                groupStorageItems
        );

        groupStorageScanned = true;
    }

    public void scanInventory(
            ItemContainer inventory)
    {
        if (inventory == null)
        {
            inventoryItems.clear();
            inventoryScanned = false;
            return;
        }

        scanContainer(
                inventory,
                inventoryItems
        );

        inventoryScanned = true;
    }

    private void scanContainer(
            ItemContainer container,
            Map<Integer, Integer> destination)
    {
        destination.clear();

        for (Item item
                : container.getItems())
        {
            if (item == null)
            {
                continue;
            }

            if (item.getId() <= 0
                    || item.getQuantity() <= 0)
            {
                continue;
            }

            destination.merge(
                    item.getId(),
                    item.getQuantity(),
                    Integer::sum
            );
        }
    }

    public int getQuantity(
            int itemId)
    {
        long total =
                (long) getBankQuantity(
                        itemId
                )
                        + getGroupStorageQuantity(
                        itemId
                )
                        + getInventoryQuantity(
                        itemId
                );

        if (total > Integer.MAX_VALUE)
        {
            return Integer.MAX_VALUE;
        }

        return (int) total;
    }

    public int getBankQuantity(
            int itemId)
    {
        return bankItems.getOrDefault(
                itemId,
                0
        );
    }

    public int getGroupStorageQuantity(
            int itemId)
    {
        return groupStorageItems.getOrDefault(
                itemId,
                0
        );
    }

    public int getInventoryQuantity(
            int itemId)
    {
        return inventoryItems.getOrDefault(
                itemId,
                0
        );
    }

    public boolean hasItem(
            int itemId)
    {
        return getQuantity(
                itemId
        ) > 0;
    }

    public boolean hasQuantity(
            int itemId,
            int quantity)
    {
        return getQuantity(
                itemId
        ) >= quantity;
    }

    public int getUniqueItemCount()
    {
        Set<Integer> uniqueItems =
                new HashSet<>();

        uniqueItems.addAll(
                bankItems.keySet()
        );

        uniqueItems.addAll(
                groupStorageItems.keySet()
        );

        return uniqueItems.size();
    }

    public long getTotalItemCount()
    {
        long total = 0;

        for (int quantity
                : bankItems.values())
        {
            total += quantity;
        }

        for (int quantity
                : groupStorageItems.values())
        {
            total += quantity;
        }

        return total;
    }

    public boolean hasScannedBank()
    {
        return bankScanned;
    }

    public boolean hasScannedGroupStorage()
    {
        return groupStorageScanned;
    }

    public boolean hasScannedInventory()
    {
        return inventoryScanned;
    }

    public BankTracker snapshot() {
        BankTracker copy = new BankTracker();
        copy.bankItems.putAll(bankItems);
        copy.groupStorageItems.putAll(groupStorageItems);
        copy.inventoryItems.putAll(inventoryItems);
        copy.bankScanned = bankScanned;
        copy.groupStorageScanned = groupStorageScanned;
        copy.inventoryScanned = inventoryScanned;
        return copy;
    }

    public void clear()
    {
        bankItems.clear();
        groupStorageItems.clear();
        inventoryItems.clear();

        bankScanned = false;
        groupStorageScanned = false;
        inventoryScanned = false;
    }
}

package com.ironquestprep;

public final class GatheringPrerequisite
{
    private final String itemName;
    private final int[] itemIds;
    private final int quantityRequired;
    private final String instruction;

    /*
     * true:
     * The item is turned into / consumed while making the
     * target item.
     *
     * Example:
     * Empty pot -> Pot of flour
     *
     * false:
     * The item is merely a reusable tool.
     *
     * Example:
     * Hammer
     */
    private final boolean consumed;

    public GatheringPrerequisite(
            String itemName,
            int[] itemIds,
            int quantityRequired,
            String instruction,
            boolean consumed)
    {
        this.itemName =
                itemName == null
                        ? ""
                        : itemName.trim();

        this.itemIds =
                itemIds == null
                        ? new int[0]
                        : itemIds.clone();

        this.quantityRequired =
                Math.max(
                        0,
                        quantityRequired
                );

        this.instruction =
                instruction == null
                        ? ""
                        : instruction.trim();

        this.consumed =
                consumed;
    }

    /*
     * Convenience constructor for one specific item ID.
     */
    public GatheringPrerequisite(
            String itemName,
            int itemId,
            int quantityRequired,
            String instruction,
            boolean consumed)
    {
        this(
                itemName,
                new int[]
                        {
                                itemId
                        },
                quantityRequired,
                instruction,
                consumed
        );
    }

    public String getItemName()
    {
        return itemName;
    }

    public int[] getItemIds()
    {
        return itemIds.clone();
    }

    public int getQuantityRequired()
    {
        return quantityRequired;
    }

    public String getInstruction()
    {
        return instruction;
    }

    public boolean isConsumed()
    {
        return consumed;
    }

    /*
     * Ownership uses the same combined BankTracker count:
     *
     * bank
     * + Group Ironman storage
     * + inventory
     */
    public int getOwnedQuantity(
            BankTracker bankTracker)
    {
        if (bankTracker == null)
        {
            return 0;
        }

        long owned =
                0;

        for (int itemId : itemIds)
        {
            if (itemId <= 0)
            {
                continue;
            }

            owned +=
                    bankTracker.getQuantity(
                            itemId
                    );

            if (owned >= Integer.MAX_VALUE)
            {
                return Integer.MAX_VALUE;
            }
        }

        return (int) owned;
    }

    public int getMissingQuantity(
            BankTracker bankTracker)
    {
        return Math.max(
                quantityRequired
                        - getOwnedQuantity(
                        bankTracker
                ),
                0
        );
    }

    public boolean isSatisfied(
            BankTracker bankTracker)
    {
        return getMissingQuantity(
                bankTracker
        ) <= 0;
    }

    public boolean hasItemIds()
    {
        return itemIds.length > 0;
    }
}

package com.ironquestprep;

import java.util.ArrayList;

import java.util.Collections;

import java.util.List;

public final class GatheringStage {

    private final String name;

    private final String instruction;

    private final GatheringTarget target;

    private final int[] completionItemIds;

    private final int completionQuantity;

    private final List<GatheringPrerequisite> prerequisites;

    public GatheringStage(

            String name,

            String instruction,

            GatheringTarget target,

            int[] completionItemIds,

            int completionQuantity) {

        this(

                name,

                instruction,

                target,

                completionItemIds,

                completionQuantity,

                Collections.emptyList());

    }

    public GatheringStage(

            String name,

            String instruction,

            GatheringTarget target,

            int[] completionItemIds,

            int completionQuantity,

            List<GatheringPrerequisite> prerequisites) {

        this.name = name == null ? "" : name.trim();

        this.instruction = instruction == null ? "" : instruction.trim();

        this.target = target == null ? GatheringTarget.none() : target;

        this.completionItemIds = completionItemIds == null ? new int[0] : completionItemIds.clone();

        this.completionQuantity = Math.max(0, completionQuantity);

        if (prerequisites == null || prerequisites.isEmpty()) {

            this.prerequisites = Collections.emptyList();

        } else {

            List<GatheringPrerequisite> safePrerequisites = new ArrayList<>();

            for (GatheringPrerequisite prerequisite : prerequisites) {

                if (prerequisite != null) {

                    safePrerequisites.add(prerequisite);

                }

            }

            this.prerequisites = Collections.unmodifiableList(safePrerequisites);

        }

    }

    public static GatheringStage itemStage(

            String name,

            String instruction,

            GatheringTarget target,

            int completionItemId,

            int completionQuantity) {

        return new GatheringStage(

                name,

                instruction,

                target,

                new int[] {completionItemId},

                completionQuantity,

                Collections.emptyList());

    }

    public static GatheringStage itemStage(

            String name,

            String instruction,

            GatheringTarget target,

            int completionItemId,

            int completionQuantity,

            List<GatheringPrerequisite> prerequisites) {

        return new GatheringStage(

                name,

                instruction,

                target,

                new int[] {completionItemId},

                completionQuantity,

                prerequisites);

    }

    public static GatheringStage navigationOnly(

            String name, String instruction, GatheringTarget target) {

        return new GatheringStage(

                name, instruction, target, new int[0], 0, Collections.emptyList());

    }

    public String getName() {

        return name;

    }

    public String getInstruction() {

        return instruction;

    }

    public GatheringTarget getTarget() {

        return target;

    }

    public int[] getCompletionItemIds() {

        return completionItemIds.clone();

    }

    public int getCompletionQuantity() {

        return completionQuantity;

    }

    public List<GatheringPrerequisite> getPrerequisites() {

        return prerequisites;

    }

    public boolean hasNavigationTarget() {

        return target != null && target.isNavigable();

    }

    public boolean hasCompletionRequirement() {

        return completionItemIds.length > 0 && completionQuantity > 0;

    }

    public boolean isComplete(BankTracker bankTracker) {

        if (bankTracker == null) {

            return false;

        }

        if (!hasCompletionRequirement()) {

            return false;

        }

        long owned = 0;

        for (int itemId : completionItemIds) {

            if (itemId <= 0) {

                continue;

            }

            owned += bankTracker.getQuantity(itemId);

            if (owned >= completionQuantity) {

                return true;

            }

        }

        return false;

    }

    public int getOwnedQuantity(BankTracker bankTracker) {

        if (bankTracker == null) {

            return 0;

        }

        long owned = 0;

        for (int itemId : completionItemIds) {

            if (itemId <= 0) {

                continue;

            }

            owned += bankTracker.getQuantity(itemId);

        }

        if (owned > Integer.MAX_VALUE) {

            return Integer.MAX_VALUE;

        }

        return (int) owned;

    }

    public int getMissingQuantity(BankTracker bankTracker) {

        if (!hasCompletionRequirement()) {

            return 0;

        }

        return Math.max(completionQuantity - getOwnedQuantity(bankTracker), 0);

    }

    public boolean hasPrerequisites() {

        return !prerequisites.isEmpty();

    }

    public boolean arePrerequisitesSatisfied(BankTracker bankTracker) {

        if (prerequisites.isEmpty()) {

            return true;

        }

        for (GatheringPrerequisite prerequisite : prerequisites) {

            if (!prerequisite.isSatisfied(bankTracker)) {

                return false;

            }

        }

        return true;

    }

    public List<GatheringPrerequisite> getMissingPrerequisites(BankTracker bankTracker) {

        if (prerequisites.isEmpty()) {

            return Collections.emptyList();

        }

        List<GatheringPrerequisite> missing = new ArrayList<>();

        for (GatheringPrerequisite prerequisite : prerequisites) {

            if (!prerequisite.isSatisfied(bankTracker)) {

                missing.add(prerequisite);

            }

        }

        return Collections.unmodifiableList(missing);

    }

    public String getPrerequisiteStatusText(BankTracker bankTracker) {

        if (prerequisites.isEmpty()) {

            return "";

        }

        StringBuilder text = new StringBuilder();

        for (GatheringPrerequisite prerequisite : prerequisites) {

            if (text.length() > 0) {

                text.append(", ");

            }

            text.append(prerequisite.getItemName());

            text.append(" ");

            text.append(

                    Math.min(

                            prerequisite.getOwnedQuantity(bankTracker),

                            prerequisite.getQuantityRequired()));

            text.append("/");

            text.append(prerequisite.getQuantityRequired());

        }

        return text.toString();

    }

}

package com.ironquestprep;

import net.runelite.api.coords.WorldPoint;

public final class GatheringTargetResolver
{
    private GatheringTargetResolver()
    {
    }

    public static GatheringTarget resolve(
            GatheringStep step)
    {
        if (step == null)
        {
            return GatheringTarget.none();
        }

        // Explicit targets supplied by a route/stage are already more specific
        // than any text-derived destination.
        if (step.hasNavigationTarget())
        {
            return step.getTarget();
        }

        GatheringTarget exactTarget =
                AcquisitionTargetDatabase.resolve(
                        step
                );

        if (exactTarget != null)
        {
            return exactTarget;
        }

        AcquisitionPlace logicalPlace =
                AcquisitionPlaceDatabase.infer(
                        step.getRegion(),
                        step.getLocation(),
                        step.getInstruction()
                );

        WorldPoint logicalPlacePoint =
                AcquisitionNavigationDatabase.getWorldPoint(
                        logicalPlace
                );

        if (logicalPlacePoint != null)
        {

            if (step.getMethodType()
                    == AcquisitionInfo.MethodType.SPAWN)
            {
                int[] ids =
                        step.getItemIds();

                if (ids.length > 0)
                {
                    return GatheringTarget.groundItem(
                            ids[0],
                            step.getItemName(),
                            logicalPlacePoint
                    );
                }
            }

            return GatheringTarget.area(
                    logicalPlace.getDisplayName(),
                    logicalPlacePoint
            );
        }

        if (step.getMethodType()
                == AcquisitionInfo.MethodType.SPAWN)
        {
            int[] ids =
                    step.getItemIds();

            if (ids.length > 0)
            {
                return unresolvedGroundItem(
                        ids[0],
                        step.getItemName()
                );
            }
        }

        if (step.getMethodType()
                == AcquisitionInfo.MethodType.NPC)
        {
            return unresolvedArea(
                    step.getLocation()
            );
        }

        if (step.getMethodType()
                == AcquisitionInfo.MethodType.SHOP)
        {
            return unresolvedArea(
                    step.getLocation()
            );
        }

        if (step.getMethodType()
                == AcquisitionInfo.MethodType.GATHER)
        {
            return unresolvedArea(
                    step.getLocation()
            );
        }

        if (step.getMethodType()
                == AcquisitionInfo.MethodType.CRAFT)
        {
            return unresolvedArea(
                    step.getLocation()
            );
        }

        return GatheringTarget.none();
    }

    private static GatheringTarget unresolvedGroundItem(
            int itemId,
            String name)
    {
        return new GatheringTarget(
                GatheringTarget.TargetType.GROUND_ITEM,
                null,
                itemId,
                name
        );
    }

    private static GatheringTarget unresolvedArea(
            String name)
    {
        return new GatheringTarget(
                GatheringTarget.TargetType.AREA,
                null,
                -1,
                name == null
                        ? ""
                        : name
        );
    }
}

package com.ironquestprep;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

/**
 * AUTO-GENERATED FILE.
 *
 * Acquisition hints extracted from Quest Helper tooltips.
 * Do not hand-edit this file.
 */
public final class GeneratedAcquisitionAdvice
{
    private static final Map<String, String> ADVICE = build();

    private GeneratedAcquisitionAdvice()
    {
    }

    public static String get(String key)
    {
        String advice = ADVICE.get(key);
        return advice == null ? "" : advice;
    }

    public static int size()
    {
        return ADVICE.size();
    }

