package com.ironquestprep;

import java.util.LinkedHashSet;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;


public final class ItemSourceResolver
{
    private static final Pattern ITEM_ID_PATTERN =
            Pattern.compile(
                    "ItemID(?:\\.Cert)?\\.[A-Za-z0-9_]+"
            );

    private ItemSourceResolver()
    {
    }

    public static int[] resolve(
            String itemSource,
            String alternateSources)
    {
        Set<Integer> itemIds =
                new LinkedHashSet<>();

        addSource(
                itemIds,
                itemSource
        );

        if (alternateSources != null
                && !alternateSources.trim().isEmpty())
        {
            String[] alternatives =
                    alternateSources.split("\\|");

            for (String alternative : alternatives)
            {
                addSource(
                        itemIds,
                        alternative
                );
            }
        }

        int[] result =
                new int[itemIds.size()];

        int index = 0;

        for (Integer itemId : itemIds)
        {
            result[index++] = itemId;
        }

        return result;
    }

    private static void addSource(
            Set<Integer> itemIds,
            String source)
    {
        if (source == null)
        {
            return;
        }

        source = source.trim();

        if (source.isEmpty()
                || source.equals("-1"))
        {
            return;
        }

        if (source.startsWith(
                "ItemCollections."))
        {
            addCollection(
                    itemIds,
                    source.substring(
                            "ItemCollections.".length()
                    )
            );

            return;
        }

        if (source.startsWith(
                "KeyringCollection."))
        {
            /*
             * Keyring unlocks are not normal bank items.
             * We'll handle these separately later.
             */
            return;
        }

        if (source.startsWith(
                "ItemID."))
        {
            Integer itemId =
                    resolveItemId(source);

            if (itemId != null
                    && itemId > 0)
            {
                itemIds.add(itemId);
            }

            return;
        }

        /*
         * Handles expressions such as:
         *
         * Arrays.asList(
         *     ItemID.X,
         *     ItemID.Y
         * )
         */
        Matcher matcher =
                ITEM_ID_PATTERN.matcher(source);

        while (matcher.find())
        {
            Integer itemId =
                    resolveItemId(
                            matcher.group()
                    );

            if (itemId != null
                    && itemId > 0)
            {
                itemIds.add(itemId);
            }
        }
    }

    private static void addCollection(
            Set<Integer> itemIds,
            String collectionName)
    {
        String[] symbolicIds =
                GeneratedItemCollections.get(
                        collectionName
                );

        for (String symbolicId : symbolicIds)
        {
            addSource(
                    itemIds,
                    symbolicId
            );
        }
    }

    private static Integer resolveItemId(String source)
    {
        return GeneratedItemIds.get(source);
    }
}

package com.ironquestprep;

import java.awt.Component;
import java.util.List;
import java.util.function.Function;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JPanel;

/** A collapsed shop/location creates no supply rows; large lists load in small batches. */
final class PagedSupplySection<T> extends JPanel {
    private static final int PAGE_SIZE = 20;
    private final List<T> items;
    private final Function<T, Component> row;
    private final JPanel body = new JPanel();
    private final JButton more = new JButton("Show more supplies");
    private int loaded;

    PagedSupplySection(String title, List<T> items, Function<T, Component> row) {
        this.items = items;
        this.row = row;
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setAlignmentX(Component.LEFT_ALIGNMENT);
        body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
        body.setVisible(false);
        JButton toggle = new JButton("+ " + title + " (" + items.size() + ")");
        toggle.setAlignmentX(Component.LEFT_ALIGNMENT);
        toggle.addActionListener(event -> {
            boolean expand = !body.isVisible();
            if (expand && loaded == 0) loadPage();
            body.setVisible(expand);
            toggle.setText((expand ? "- " : "+ ") + title + " (" + items.size() + ")");
            revalidate();
            repaint();
        });
        more.addActionListener(event -> loadPage());
        more.setAlignmentX(Component.LEFT_ALIGNMENT);
        add(toggle);
        add(body);
    }

    private void loadPage() {
        body.remove(more);
        int end = Math.min(items.size(), loaded + PAGE_SIZE);
        while (loaded < end) body.add(row.apply(items.get(loaded++)));
        if (loaded < items.size()) body.add(more);
        revalidate();
        repaint();
    }
}

