package com.ironquestprep;

import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.client.callback.ClientThread;

import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Tile;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.AccountHashChanged;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.ItemDespawned;
import net.runelite.api.events.ItemSpawned;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
        name = "Ironman Quest Prep",
        configName = "ironquestprepplugin",
        description =
                "Quest preparation checklist, gathering destinations and quest reward XP planning",
        tags = {"ironman", "quest", "items", "prep", "checklist"})
@lombok.extern.slf4j.Slf4j
public class QuestPrepPlugin extends Plugin {
    @Inject private ClientToolbar clientToolbar;

    @Inject private Client client;

    @Inject private OverlayManager overlayManager;

    @Inject private QuestGroundItemOverlay groundItemOverlay;

    @Inject private RouteGuidanceOverlay routeGuidanceOverlay;

    @Inject private ConfigManager configManager;

    @Inject private ClientThread clientThread;

    private IronQuestprepPanel panel;
    private NavigationButton navButton;

    private final BankTracker bankTracker = new BankTracker();

    private List<RequiredItem> activeRequirements = Collections.emptyList();

    private final Map<Tile, Integer> groundItemTileCounts = new HashMap<>();

    private long lastAccountHash = -1L;

    private final GroundItemLabels groundLabels = new GroundItemLabels();
    private final QuestSkillPlanner.Cache skillPlanCache = new QuestSkillPlanner.Cache();
    private QuestSkillPlanner.Plan displayedPlan;
    private boolean ownershipDirty;
    private final SkillRefreshSchedule skillRefreshSchedule = new SkillRefreshSchedule();

    @Override
    protected void startUp() {
        bankTracker.clear();
        groundLabels.clear();
        skillPlanCache.clear();
        displayedPlan = null;
        ownershipDirty = false;
        skillRefreshSchedule.reset();

        activeRequirements = Collections.emptyList();

        groundItemTileCounts.clear();

        routeGuidanceOverlay.clearActiveStep();

        lastAccountHash = client.getAccountHash();

        panel = new IronQuestprepPanel();

        /*
         * Manual route selection from the Gathering Route
         * panel.
         */
        panel.setRouteStepSelectionListener(
                step -> clientThread.invokeLater(() -> selectRouteStep(step)));

        BufferedImage icon = QuestIcon.create();

        navButton =
                NavigationButton.builder()
                        .tooltip("Ironman Quest Prep")
                        .icon(icon)
                        .priority(5)
                        .panel(panel)
                        .build();

        clientToolbar.addNavigation(navButton);

        overlayManager.add(groundItemOverlay);

        log.debug("Ironman Quest Prep started!");
    }

    private void selectRouteStep(GatheringStep step) {
        if (step == null) {
            return;
        }

        if (!step.hasNavigationTarget()) {
            return;
        }

        configManager.setConfiguration("ironquesthelper", "routeGuidance", true);
        routeGuidanceOverlay.clearActiveStep();
        routeGuidanceOverlay.setActiveStep(step);

        log.debug(
                "Ironman Quest Prep: navigating to "
                        + step.getItemName()
                        + " at "
                        + step.getTarget().getCoordinateText());
    }

    @Subscribe
    public void onAccountHashChanged(AccountHashChanged event) {
        long currentAccountHash = client.getAccountHash();

        if (currentAccountHash == -1L) {
            return;
        }

        if (lastAccountHash != -1L && currentAccountHash != lastAccountHash) {
            bankTracker.clear();
            groundLabels.clear();
            skillPlanCache.clear();
            displayedPlan = null;
            ownershipDirty = false;

            activeRequirements = Collections.emptyList();

            groundItemTileCounts.clear();

            routeGuidanceOverlay.clearActiveStep();

            if (panel != null) {
                panel.resetForAccountChange();
                skillRefreshSchedule.reset();
            }

            log.debug("Ironman Quest Prep: account changed - cached item data cleared.");
        }

        lastAccountHash = currentAccountHash;
    }

    @Subscribe
    public void onWidgetLoaded(net.runelite.api.events.WidgetLoaded event) {
        if (event.getGroupId() == net.runelite.api.gameval.InterfaceID.BANKMAIN) {
            net.runelite.api.ItemContainer bank = client.getItemContainer(InventoryID.BANK);
            if (bank != null) {
                bankTracker.scanBank(bank);
                bankTracker.scanInventory(client.getItemContainer(InventoryID.INV));
                ownershipDirty = true;
            }
        }
    }

    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event) {
        int containerId = event.getContainerId();

        /*
         * Player bank.
         */
        if (containerId == InventoryID.BANK) {
            bankTracker.scanBank(event.getItemContainer());

            ownershipDirty = true;

            return;
        }

        /*
         * Group Ironman shared storage.
         */
        if (containerId == InventoryID.INV_GROUP_TEMP) {
            bankTracker.scanGroupStorage(event.getItemContainer());

            if (bankTracker.hasScannedBank()) {
                ownershipDirty = true;
            }

            return;
        }

        /*
         * Player inventory.
         *
         * Inventory now counts towards quest-prep ownership.
         */
        if (containerId == InventoryID.INV) {
            bankTracker.scanInventory(event.getItemContainer());

            groundLabels.rebuild(activeRequirements, bankTracker);
        }
    }

    @Subscribe
    public void onItemSpawned(ItemSpawned event) {
        Tile tile = event.getTile();

        if (tile == null) {
            return;
        }

        groundItemTileCounts.merge(tile, 1, Integer::sum);
    }

    @Subscribe
    public void onItemDespawned(ItemDespawned event) {
        Tile tile = event.getTile();

        if (tile == null) {
            return;
        }

        Integer count = groundItemTileCounts.get(tile);

        if (count == null) {
            return;
        }

        if (count <= 1) {
            groundItemTileCounts.remove(tile);
        } else {
            groundItemTileCounts.put(tile, count - 1);
        }
    }

    @Subscribe
    public void onConfigChanged(net.runelite.client.events.ConfigChanged event) {
        if ("ironquesthelper".equals(event.getGroup()) && "routeGuidance".equals(event.getKey())) {
            clientThread.invokeLater(() -> routeGuidanceOverlay.setActiveStep(routeGuidanceOverlay.getActiveStep()));
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event) {
        GameState state = event.getGameState();
        skillRefreshSchedule.setPlaying(state == GameState.LOGGED_IN, System.nanoTime());
        if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING) skillRefreshSchedule.reset();
        if (state == GameState.LOGIN_SCREEN) {
            skillPlanCache.clear();
            displayedPlan = null;
            groundLabels.clear();
            if (panel != null) panel.updateSkills(null);
        }

        if (state == GameState.LOADING
                || state == GameState.HOPPING
                || state == GameState.LOGIN_SCREEN) {
            groundItemTileCounts.clear();
        }
        if (state == GameState.LOGIN_SCREEN) {
            routeGuidanceOverlay.clearActiveStep();
        }
    }

    @Subscribe
    public void onGameTick(GameTick event) {
        if (client.getGameState() == GameState.LOGGED_IN
                && panel != null
                && skillRefreshSchedule.refreshDue(System.nanoTime())) {
            QuestSkillPlanner.Plan nextPlan = skillPlanCache.snapshot(client);
            if (nextPlan != displayedPlan) {
                panel.updateSkills(nextPlan);
                displayedPlan = nextPlan;
            }
        }
        if (ownershipDirty
                && bankTracker.hasScannedBank()
                && client.getGameState() == GameState.LOGGED_IN) {
            refreshChecklist();
        }
    }

    private void refreshChecklist() {
        ownershipDirty = false;
        List<QuestItemDatabase.QuestSupplies> questSupplies = QuestItemDatabase.getQuestSupplies(client, bankTracker);
        List<RequiredItem> requirements = QuestItemDatabase.combineSupplies(questSupplies);

        activeRequirements = new ArrayList<>(requirements);
        groundLabels.rebuild(activeRequirements, bankTracker);

        refreshRouteGuidance(requirements);

        if (panel != null) {
            panel.updateBankStatus(
                    bankTracker.getUniqueItemCount(), bankTracker.getTotalItemCount());

            panel.updateChecklist(bankTracker.snapshot(), requirements, questSupplies);
        }
    }

    private WorldPoint getPlayerWorldPoint() {
        if (client.getLocalPlayer() == null) {
            return null;
        }

        return client.getLocalPlayer().getWorldLocation();
    }

    private void refreshRouteGuidance(List<RequiredItem> requirements) {
        WorldPoint playerLocation = getPlayerWorldPoint();

        /*
         * THIS is the important change.
         *
         * The route is now built using the player's current
         * position instead of purely alphabetical ordering.
         */
        List<GatheringStep> steps =
                GatheringRouteBuilder.build(requirements, bankTracker, playerLocation);

        /*
         * Preserve the manually selected destination while
         * it is still required.
         */
        GatheringStep currentStep = routeGuidanceOverlay.getActiveStep();

        if (currentStep != null) {
            for (GatheringStep step : steps) {
                if (!step.hasNavigationTarget()) {
                    continue;
                }

                if (isSameRouteStep(currentStep, step)) {
                    routeGuidanceOverlay.setActiveStep(step);

                    return;
                }
            }
        }

        routeGuidanceOverlay.clearActiveStep();
    }

    private boolean isSameRouteStep(GatheringStep first, GatheringStep second) {
        if (first == null || second == null) {
            return false;
        }

        if (first.getRegion() != second.getRegion()) {
            return false;
        }

        if (!safeText(first.getItemName()).equalsIgnoreCase(safeText(second.getItemName()))) {
            return false;
        }

        return safeText(first.getLocation()).equalsIgnoreCase(safeText(second.getLocation()));
    }

    private String safeText(String text) {
        return text == null ? "" : text.trim();
    }

    String getGroundItemLabel(int groundItemId) {
        return groundLabels.get(groundItemId);
    }

    boolean hasGroundItemLabels() { return !groundLabels.isEmpty(); }

    Set<Tile> getGroundItemTiles() {
        // Both the overlay and item events run on the client thread.
        return Collections.unmodifiableSet(groundItemTileCounts.keySet());
    }

    @Override
    protected void shutDown() {
        overlayManager.remove(groundItemOverlay);

        skillRefreshSchedule.reset();

        routeGuidanceOverlay.clearActiveStep();

        bankTracker.clear();
        groundLabels.clear();
        skillPlanCache.clear();
        displayedPlan = null;
        ownershipDirty = false;

        activeRequirements = Collections.emptyList();

        groundItemTileCounts.clear();

        lastAccountHash = -1L;

        if (navButton != null) {
            clientToolbar.removeNavigation(navButton);
        }

        panel = null;
        navButton = null;

        log.debug("Ironman Quest Prep stopped!");
    }

    @Provides
    QuestPrepConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(QuestPrepConfig.class);
    }
}

package com.ironquestprep;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.api.Quest;

public class QuestRequirement
{
    private final String sourceKey;
    private final Quest quest;
    private final List<RequiredItem> items;
    private final List<RequirementGroup> groups;
    private final List<String> rootRequirements;
    private final List<String> advisories;

    /*
     * Existing constructor.
     *
     * This keeps the current manually-written QuestItemDatabase
     * completely compatible while we build the generated database.
     */
    public QuestRequirement(
            Quest quest,
            RequiredItem... items)
    {
        this(
                quest == null ? "" : quest.name(),
                quest,
                Arrays.asList(items),
                Collections.emptyList(),
                Collections.emptyList(),
                Collections.emptyList()
        );
    }

    /*
     * Constructor used by generated quest data.
     */
    public QuestRequirement(
            String sourceKey,
            Quest quest,
            List<RequiredItem> items,
            List<RequirementGroup> groups,
            List<String> rootRequirements,
            List<String> advisories)
    {
        this.sourceKey =
                sourceKey == null
                        ? ""
                        : sourceKey;

        this.quest = quest;

        this.items = Collections.unmodifiableList(
                new ArrayList<>(items)
        );

        this.groups = Collections.unmodifiableList(
                new ArrayList<>(groups)
        );

        this.rootRequirements = Collections.unmodifiableList(
                new ArrayList<>(rootRequirements)
        );

        this.advisories = Collections.unmodifiableList(
                new ArrayList<>(advisories)
        );
    }

    public String getSourceKey()
    {
        return sourceKey;
    }

    public Quest getQuest()
    {
        return quest;
    }

    public List<RequiredItem> getItems()
    {
        return items;
    }

    public List<RequirementGroup> getGroups()
    {
        return groups;
    }

    public List<String> getRootRequirements()
    {
        return rootRequirements;
    }

    public List<String> getAdvisories()
    {
        return advisories;
    }

    public boolean hasGeneratedStructure()
    {
        return !groups.isEmpty()
                || !rootRequirements.isEmpty()
                || !advisories.isEmpty();
    }
}

package com.ironquestprep;

import java.util.*;
import net.runelite.api.Client;
import net.runelite.api.Experience;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.gameval.VarPlayerID;

/** Pure XP planning: each requirement is paid before its quest reward is applied. */
final class QuestSkillPlanner
{
    static final class QuestData
    {
        final String id;
        final boolean cape;
        final Map<Skill, Integer> levels;
        final Map<Skill, Integer> rewards;
        final Set<String> dependencies;
        final int requiredPoints, points;
        final String notes, choices;

        QuestData(String id, boolean cape, String levels, String rewards, String dependencies,
                  int requiredPoints, int points, String notes, String choices)
        {
            this.id = id;
            this.cape = cape;
            this.levels = parse(levels);
            this.rewards = parse(rewards);
            this.dependencies = dependencies.isEmpty() ? Collections.emptySet()
                    : new LinkedHashSet<>(Arrays.asList(dependencies.split(",")));
            this.requiredPoints = requiredPoints;
            this.points = points;
            this.notes = notes;
            this.choices = choices;
        }

        private static Map<Skill, Integer> parse(String value)
        {
            Map<Skill, Integer> result = new EnumMap<>(Skill.class);
            if (!value.isEmpty())
                for (String part : value.split(","))
                {
                    String[] pair = part.split(":");
                    result.put(Skill.valueOf(pair[0]), Integer.parseInt(pair[1]));
                }
            return Collections.unmodifiableMap(result);
        }
    }

    static final class Step
    {
        final QuestData quest;
        final Map<Skill, Long> training, rewards, after;
        Step(QuestData quest, Map<Skill, Long> training, Map<Skill, Long> rewards, Map<Skill, Long> after)
        {
            this.quest = quest;
            this.training = Collections.unmodifiableMap(new EnumMap<>(training));
            this.rewards = Collections.unmodifiableMap(new EnumMap<>(rewards));
            this.after = Collections.unmodifiableMap(new EnumMap<>(after));
        }
    }

    static final class Plan
    {
        final Map<Skill, Integer> targets = new EnumMap<>(Skill.class);
        final Map<Skill, Integer> remainingTargets = new EnumMap<>(Skill.class);
        final Map<Skill, Long> current = new EnumMap<>(Skill.class);
        final Map<Skill, Long> training = new EnumMap<>(Skill.class);
        final List<Step> steps = new ArrayList<>();
        final List<String> unresolved = new ArrayList<>();
        final List<String> unavailable = new ArrayList<>();
        final Map<Skill, String> targetQuests = new EnumMap<>(Skill.class);
    }

    private static final List<QuestData> DATA = GeneratedQuestSkills.load();

    private static Input capture(Client client)
    {
        Map<Skill, Long> xp = new EnumMap<>(Skill.class);
        for (Skill skill : Skill.values())
            if (skill != Skill.OVERALL) xp.put(skill, (long) client.getSkillExperience(skill));
        Set<String> finished = new HashSet<>();
        Set<String> started = new HashSet<>();
        List<QuestData> supported = new ArrayList<>();
        List<String> unavailable = new ArrayList<>();
        for (QuestData data : DATA)
        {
            try
            {
                Quest quest = Quest.valueOf(data.id);
                QuestState state = quest.getState(client);
                supported.add(data);
                if (state == QuestState.FINISHED) finished.add(data.id);
                else if (state == QuestState.IN_PROGRESS) started.add(data.id);
            }
            catch (IllegalArgumentException exception)
            {
                // Do not silently describe an older client's incomplete data as a full cape plan.
                unavailable.add(data.id);
            }
        }
        return new Input(supported, xp, finished, started,
                client.getVarpValue(VarPlayerID.QP), unavailable);
    }

    static final class Input {
        final List<QuestData> data;
        final Map<Skill, Long> xp;
        final Set<String> finished, started;
        final int points;
        final List<String> unavailable;
        Input(List<QuestData> data, Map<Skill, Long> xp, Set<String> finished,
              Set<String> started, int points, List<String> unavailable) {
            this.data = data; this.xp = new EnumMap<>(xp);
            this.finished = new HashSet<>(finished); this.started = new HashSet<>(started);
            this.points = points; this.unavailable = new ArrayList<>(unavailable);
        }
        boolean same(Input other) {
            return other != null && points == other.points && xp.equals(other.xp)
                    && finished.equals(other.finished) && started.equals(other.started)
                    && unavailable.equals(other.unavailable) && data.equals(other.data);
        }
        Plan calculate() {
            Plan plan = QuestSkillPlanner.calculate(data, xp, finished, started, points);
            plan.unavailable.addAll(unavailable);
            return plan;
        }
    }

    static final class Cache {
        private Input previous;
        private Plan plan;
        Plan snapshot(Client client) { return update(capture(client)); }
        Plan update(Input input) {
            if (!input.same(previous)) {
                plan = input.calculate();
                previous = input;
            }
            return plan;
        }
        void clear() { previous = null; plan = null; }
    }

    static Plan snapshot(Client client) { return capture(client).calculate(); }

    static Plan calculate(List<QuestData> data, Map<Skill, Long> current,
                          Set<String> finished, Set<String> started, int questPoints)
    {
        Plan plan = new Plan();
        plan.current.putAll(current);
        Map<String, QuestData> index = new LinkedHashMap<>();
        for (QuestData q : data) index.put(q.id, q);
        Set<String> needed = new LinkedHashSet<>();
        for (QuestData q : data) if (q.cape) collect(q.id, index, needed);
        for (String id : needed)
        {
            QuestData q = index.get(id);
            if (q == null) continue;
            if (!finished.contains(id))
                for (Map.Entry<Skill, Integer> requirement : q.levels.entrySet())
                    plan.remainingTargets.merge(requirement.getKey(), requirement.getValue(), Math::max);
            for (Map.Entry<Skill, Integer> requirement : q.levels.entrySet())
                if (requirement.getValue() > plan.targets.getOrDefault(requirement.getKey(), 1))
                {
                    plan.targets.put(requirement.getKey(), requirement.getValue());
                    plan.targetQuests.put(requirement.getKey(), q.id);
                }
        }
        Set<String> done = new HashSet<>(finished);
        Map<Skill, Long> xp = new EnumMap<>(Skill.class);
        xp.putAll(current);
        List<QuestData> pending = new ArrayList<>();
        for (QuestData q : data) if (needed.contains(q.id) && !done.contains(q.id)) pending.add(q);
        int points = questPoints;
        while (!pending.isEmpty())
        {
            QuestData best = null;
            long bestCost = Long.MAX_VALUE;
            for (QuestData q : pending)
            {
                if (!done.containsAll(q.dependencies) || points < q.requiredPoints) continue;
                long cost = 0;
                for (Map.Entry<Skill, Integer> req : q.levels.entrySet())
                    cost += Math.max(0, threshold(req.getValue()) - xp.getOrDefault(req.getKey(), 0L));
                if (cost < bestCost || (cost == bestCost && (best == null || q.id.compareTo(best.id) < 0)))
                {
                    best = q;
                    bestCost = cost;
                }
            }
            if (best == null)
            {
                for (QuestData q : pending) plan.unresolved.add(q.id);
                break;
            }
            Map<Skill, Long> train = new EnumMap<>(Skill.class);
            Map<Skill, Long> reward = new EnumMap<>(Skill.class);
            for (Map.Entry<Skill, Integer> req : best.levels.entrySet())
            {
                long amount = Math.max(0, threshold(req.getValue()) - xp.getOrDefault(req.getKey(), 0L));
                if (amount > 0)
                {
                    train.put(req.getKey(), amount);
                    plan.training.merge(req.getKey(), amount, Long::sum);
                    xp.merge(req.getKey(), amount, Long::sum);
                }
            }
            // In-quest XP may already be included in live XP. Until stage-specific
            // remaining rewards are mapped, exclude rewards of started quests.
            if (!started.contains(best.id))
                for (Map.Entry<Skill, Integer> gain : best.rewards.entrySet())
                {
                    reward.put(gain.getKey(), gain.getValue().longValue());
                    xp.merge(gain.getKey(), gain.getValue().longValue(), Long::sum);
                }
            plan.steps.add(new Step(best, train, reward, xp));
            if (!("RECIPE_FOR_DISASTER".equals(best.id) && started.contains(best.id))) points += best.points;
            done.add(best.id);
            pending.remove(best);
        }
        return plan;
    }

    private static void collect(String id, Map<String, QuestData> data, Set<String> needed)
    {
        if (!needed.add(id)) return;
        QuestData q = data.get(id);
        if (q != null) for (String dependency : q.dependencies) collect(dependency, data, needed);
    }

    static long threshold(int level) { return Experience.getXpForLevel(level); }
    static int level(long xp) { return Experience.getLevelForXp((int) Math.min(200_000_000L, xp)); }

    static String name(String id)
    {
        try { return Quest.valueOf(id).getName(); }
        catch (IllegalArgumentException exception) { return id.replace('_', ' '); }
    }
}

package com.ironquestprep;

import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.BorderLayout;
