import org.junit.Test;
import static org.junit.Assert.*;

public class BankBrowsingTest {
    private ItemContainer container(int quantity) {
        return new ItemContainer() {
            public int getId() {return 0;}
            public Item[] getItems() {return new Item[]{new Item(ItemID.HAMMER, quantity)};}
            public Item getItem(int slot) {return getItems()[slot];}
            public boolean contains(int id) {return id == ItemID.HAMMER;}
            public int count(int id) {return contains(id) ? quantity : 0;}
            public int size() {return 1;}
            public int count() {return 1;}
            public int find(int id) {return contains(id) ? 0 : -1;}
            public Node getNext() {return null;}
            public Node getPrevious() {return null;}
            public long getHash() {return 0;}
        };
    }

    @Test public void bankSnapshotStaysFixedUntilNextRefresh() {
        BankTracker live = new BankTracker();
        live.scanBank(container(2));
        live.scanInventory(container(3));
        BankTracker snapshot = live.snapshot();
        live.scanInventory(container(10));
        live.scanBank(container(4));
        assertEquals(5, snapshot.getQuantity(ItemID.HAMMER));
        assertTrue(snapshot.hasScannedBank());
        assertEquals(14, live.snapshot().getQuantity(ItemID.HAMMER));
        live.clear();
        assertEquals(5, snapshot.getQuantity(ItemID.HAMMER));
    }

    @Test public void collapsedListsBuildNoRowsAndExpandInBatches() throws Exception {
        SwingUtilities.invokeAndWait(() -> {
            List<Integer> supplies = new ArrayList<>();
            for (int i = 0; i < 45; i++) supplies.add(i);
            AtomicInteger built = new AtomicInteger();
            PagedSupplySection<Integer> section = new PagedSupplySection<>("Shop", supplies, i -> {
                built.incrementAndGet();
                return new JLabel(i.toString());
            });
            assertEquals(0, built.get());
            JButton toggle = (JButton) section.getComponent(0);
            toggle.doClick();
            assertEquals(20, built.get());
            toggle.doClick();
            toggle.doClick();
            assertEquals(20, built.get());
            JPanel body = (JPanel) section.getComponent(1);
            ((JButton) body.getComponent(body.getComponentCount() - 1)).doClick();
            assertEquals(40, built.get());
            ((JButton) body.getComponent(body.getComponentCount() - 1)).doClick();
            assertEquals(45, built.get());
            assertEquals(45, body.getComponentCount());
        });
    }

    @Test public void catalogUsesOnlyKnownNormalStock() {
        assertEquals(AcquisitionRegion.MISTHALIN, ShopSupplyCatalog.preferredSource("ItemID.HAMMER").getRegion());
        assertNull(ShopSupplyCatalog.preferredSource("ItemID.BUCKET_MILK"));
        assertNull(ShopSupplyCatalog.preferredSource("ItemID.PESTLE_AND_MORTAR"));
    }
}

package com.ironquestprep;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;
public class GeneratedMappingIntegrityTest {
    @Test public void everyClassificationMatchesOriginalMapping() throws Exception {
        Map<String, GeneratedPrepClassification.Type> values = new TreeMap<>(GeneratedPrepClassification.build());
        assertEquals(1129, values.size());
        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        DataOutputStream out = new DataOutputStream(bytes);
        for (Map.Entry<String, GeneratedPrepClassification.Type> entry : values.entrySet()) {
            for (String field : Arrays.asList(entry.getKey(), entry.getValue().name())) {
                byte[] encoded = field.getBytes(StandardCharsets.UTF_8);
                out.writeInt(encoded.length); out.write(encoded);
            }
        }
        StringBuilder hash = new StringBuilder();
        for (byte b : MessageDigest.getInstance("SHA-256").digest(bytes.toByteArray()))
            hash.append(String.format("%02x", b & 0xff));
        assertEquals("ece2335422d6a991cb82e6efe061df326204ba86b1e8b8111305d555263db172", hash.toString());
        assertEquals(GeneratedPrepClassification.Type.QUEST_OBTAINED,
                GeneratedPrepClassification.get("unknown", "unknown"));
    }
    @Test public void itemSymbolsStillRequireTheirNamespace() {
        assertEquals(Integer.valueOf(net.runelite.api.gameval.ItemID.KNIFE), GeneratedItemIds.get("ItemID.KNIFE"));
        assertNull(GeneratedItemIds.get("KNIFE"));
        assertNull(GeneratedItemIds.get("ItemID.NOT_A_REAL_ITEM"));
        assertNull(GeneratedItemIds.get(null));
    }
}

package com.ironquestprep;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
public class GeneratedQuestDataIntegrityTest {
    private static void field(DataOutputStream out, String value) throws IOException {
        byte[] bytes = value.getBytes(StandardCharsets.UTF_8);
        out.writeInt(bytes.length); out.write(bytes);
    }
    static String fingerprint() throws Exception {
        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        DataOutputStream out = new DataOutputStream(bytes);
        for (java.util.List<GeneratedQuestData.RawItem> rows : java.util.Arrays.asList(
                GeneratedQuestData.getItems(), GeneratedQuestData.getAdvisories())) {
            out.writeInt(rows.size());
            for (GeneratedQuestData.RawItem row : rows) {
            field(out, row.getQuest());
            field(out, row.getVariable());
            field(out, row.getRequirementClass());
            field(out, row.getItemName());
            field(out, row.getItemSource());
            field(out, row.getSourceType());
            field(out, row.getQuantity());
            field(out, Boolean.toString(row.isConsumed()));
            field(out, row.getAlternateSources());
            field(out, row.getCondition());
            field(out, row.getGroup());
            field(out, row.getConditionsJson());
            field(out, row.getStatus());
            field(out, row.getReason());
            field(out, row.getOriginalReview());
            field(out, row.getSourceFile());
            }
        }
        out.writeInt(GeneratedQuestData.getGroups().size());
        for (GeneratedQuestData.RawGroup row : GeneratedQuestData.getGroups()) {
            field(out, row.getQuest());
            field(out, row.getGroup());
            field(out, row.getLogic());
            field(out, row.getChildren());
            field(out, row.getDescription());
            field(out, row.getArgumentText());
            field(out, row.getCondition());
            field(out, row.getConditionsJson());
            field(out, Boolean.toString(row.isConsumed()));
            field(out, row.getStatus());
            field(out, row.getReason());
            field(out, row.getOriginalReview());
            field(out, row.getBranchesJson());
            field(out, row.getSourceFile());
        }
        out.flush();
        StringBuilder hex = new StringBuilder();
        for (byte b : MessageDigest.getInstance("SHA-256").digest(bytes.toByteArray()))
            hex.append(String.format("%02x", b & 0xff));
        return hex.toString();
    }
    @org.junit.Test
    public void compactDataPreservesEveryOriginalFieldAndRowOrder() throws Exception {
        org.junit.Assert.assertEquals("29d7afd5a276b571f7228f49c9780b346d9d8d8859ff9230f3babcc214b3ef90", fingerprint());
        org.junit.Assert.assertEquals(1129, GeneratedQuestData.getItems().size());
        org.junit.Assert.assertEquals(97, GeneratedQuestData.getAdvisories().size());
        org.junit.Assert.assertEquals(61, GeneratedQuestData.getGroups().size());
    }
    public static void main(String[] args) throws Exception { System.out.println(fingerprint()); }
}

